def quantized_size_gb(num_params: int, bytes_per_param: float) -> float:
    """Model weight size in GB: num_params x bytes_per_param, converted to GB."""
    total_bytes = num_params * bytes_per_param
    return round(total_bytes / 1e9, 2)

print(quantized_size_gb(7_000_000_000, 2))
